#!/usr/bin/env python3
"""把「快捷」按钮的图标写进源码树（/assets/shortcut-btn.png）。

build 时源码树是上游 v0.24.1，我们的 assets 不在里面，所以 `include_bytes!` 会找不到文件。
这个补丁把缩小过的图标（128×128，17041 字节）以 base64 内联写入，
构建时落到 `crates/ui-egui/assets/shortcut-btn.png`。
"""
from __future__ import annotations

import base64
import os
from pathlib import Path

MARKER = "EFFECTCRAFT_OURS_SHORTCUT_ICON_V1"
DATA = ""


def main() -> None:
    root = Path(os.environ["EFFECTCRAFT_DIR"]).resolve()
    path = root / "crates/ui-egui/assets/shortcut-btn.png"
    path.parent.mkdir(parents=True, exist_ok=True)
    data = base64.b64decode(DATA)
    if not path.exists() or path.read_bytes() != data:
        path.write_bytes(data)
        print(f"shortcut icon written ({len(data)} bytes)")
    else:
        print("shortcut icon already in place")
